    func ?? ffi.nullptr,
    data ?? ffi.nullptr,
  );
}

/// Returns whether there are any handlers connected to @instance for the
/// given signal id and detail.
///
/// If @detail is 0 then it will only match handlers that were connected
/// without detail.  If @detail is non-zero then it will match handlers
/// connected both without detail and with the given detail.  This is
/// consistent with how a signal emitted with @detail would be delivered
/// to those handlers.
///
/// Since 2.46 this also checks for a non-default class closure being
/// installed, as this is basically always what you want.
///
/// One example of when you might use this is when the arguments to the
/// signal are difficult to compute. A class implementor may opt to not
/// emit the signal if no one is attached anyway, thus saving the cost
/// of building the arguments.
final _gSignalHasHandlerPending =
    gobjectLookup<
          ffi.NativeFunction<
            ffi.Int32 Function(
              ffi.Pointer<ffi.Void>,
              ffi.Uint32,
              ffi.Uint32,
              ffi.Int32,
            )
          >
        >('g_signal_has_handler_pending')
        .asFunction<int Function(ffi.Pointer<ffi.Void>, int, int, int)>();
bool signalHasHandlerPending(
  GObject instance,
  int signalId,
  int detail,
  bool mayBeBlocked,
) {
  return (_gSignalHasHandlerPending(
        instance.handle,
        signalId,
        detail,
        mayBeBlocked ? 1 : 0,
      )) !=
      0;
}

/// Validate a signal name. This can be useful for dynamically-generated signals
/// which need to be validated at run-time before actually trying to create them.
///
/// See [func@GObject.signal_new] for details of the rules for valid names.
/// The rules for signal names are the same as those for property names.
final _gSignalIsValidName =
    gobjectLookup<ffi.NativeFunction<ffi.Int32 Function(ffi.Pointer<Utf8>)>>(
      'g_signal_is_valid_name',
    ).asFunction<int Function(ffi.Pointer<Utf8>)>();
bool signalIsValidName(String name) {
  return withNativeString(name, (nativeName) {
    return (_gSignalIsValidName(nativeName.cast<Utf8>())) != 0;
  });
}

/// Lists the signals by id that a certain instance or interface type
/// created. Further information about the signals can be acquired through
/// g_signal_query().
final _gSignalListIds =
    gobjectLookup<
          ffi.NativeFunction<
            ffi.Pointer<ffi.Uint32> Function(ffi.Size, ffi.Pointer<ffi.Uint32>)
          >
        >('g_signal_list_ids')
        .asFunction<
          ffi.Pointer<ffi.Uint32> Function(int, ffi.Pointer<ffi.Uint32>)
        >();
(ffi.Pointer<ffi.Uint32>, int) signalListIds(int itype) {
  final _out0 = malloc<ffi.Uint32>();
  try {
    final _ret = _gSignalListIds(itype, _out0);
    return (_ret, _out0.value);
  } finally {
    malloc.free(_out0);
  }
}

/// Given the name of the signal and the type of object it connects to, gets
/// the signal's identifying integer. Emitting the signal by number is
/// somewhat faster than using the name each time.
///
/// Also tries the ancestors of the given type.
///
/// The type class passed as @itype must already have been instantiated (for
/// example, using g_type_class_ref()) for this function to work, as signals are
/// always installed during class initialization.
///
/// See g_signal_new() for details on allowed signal names.
final _gSignalLookup =
    gobjectLookup<
          ffi.NativeFunction<ffi.Uint32 Function(ffi.Pointer<Utf8>, ffi.Size)>
        >('g_signal_lookup')
        .asFunction<int Function(ffi.Pointer<Utf8>, int)>();
int signalLookup(String name, int itype) {
  return withNativeString(name, (nativeName) {
    return _gSignalLookup(nativeName.cast<Utf8>(), itype);
  });
}

/// Given the signal's identifier, finds its name.
///
/// Two different signals may have the same name, if they have differing types.
final _gSignalName =
    gobjectLookup<ffi.NativeFunction<ffi.Pointer<Utf8> Function(ffi.Uint32)>>(
      'g_signal_name',
    ).asFunction<ffi.Pointer<Utf8> Function(int)>();
String? signalName(int signalId) {
  return stringFromNative((_gSignalName(signalId)).cast(), free: false);
}

/// Overrides the class closure (i.e. the default handler) for the given signal
/// for emissions on instances of @instance_type. @instance_type must be derived
/// from the type to which the signal belongs.
///
/// See g_signal_chain_from_overridden() and
/// g_signal_chain_from_overridden_handler() for how to chain up to the
/// parent class closure from inside the overridden one.
final _gSignalOverrideClassClosure =
    gobjectLookup<
          ffi.NativeFunction<
            ffi.Void Function(ffi.Uint32, ffi.Size, ffi.Pointer<ffi.Void>)
          >
        >('g_signal_override_class_closure')
        .asFunction<void Function(int, int, ffi.Pointer<ffi.Void>)>();
void signalOverrideClassClosure(
  int signalId,
  int instanceType,
  GClosure classClosure,
) {
  _gSignalOverrideClassClosure(signalId, instanceType, classClosure.handle);
}
